let simulationAudioPlayer=null;
function getAudioPlayer(){return simulationAudioPlayer||(simulationAudioPlayer=window.GakuSimulationAudio?.createPlayer(window))}
function stopAudio(){simulationAudioPlayer?.stop();window.speechSynthesis?.cancel();playing=false}
function announce(s){$('#simulation-announce').textContent=s}
function openDialog(title,body,actions){const d=$('#simulation-dialog');d.innerHTML='<span class="eyebrow">SIMULASI DEX GAKU</span><h2 id="simulation-dialog-title">'+title+'</h2>'+qualifyHandlers(body)+'<div class="dialog-actions">'+qualifyHandlers(actions)+'</div>';if(!d.open)d.showModal()}
