function rawResult(exam,run){const qs=getPack(exam,run.pack)?.questions||[];const correct=qs.filter((q,i)=>run.answers[i]===q.answer).length;return {correct,total:qs.length,answered:run.answers.filter(v=>Number.isInteger(v)).length,sections:EXAMS[exam].sections.map((name,section)=>{const indices=qs.map((q,i)=>q.section===section?i:-1).filter(i=>i>=0);return {name,total:indices.length,correct:indices.filter(i=>run.answers[i]===qs[i].answer).length}})}}
function sectionRemaining(now=Date.now()){if(!state.run||state.run.finishedAt)return 0;return Math.max(0,Math.ceil((state.run.deadline-now)/1000))}
