function applyNavigation(view){stopAudio();if(state.run?.finishedAt&&['menu','packages'].includes(view))state.run=null;state.view=view;state.accepted=false;if(view!=='packages')delete state.recovery;persist();render();window.scrollTo({top:0,behavior:'instant'})}
